    z_t4892_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t4892_t* boxed = (z_t4892_t*)z_xmalloc(sizeof(z_t4892_t));
    *boxed = fs;
    result.tag = Z_T4900_TAG_1;
    result.data = boxed;
    return result;
