/* os.hostArchName -- the CPU family this translation unit was compiled for.
   Companion to _Z_OS_HOST_OS_NAME; same reasoning for returning a name. */
static z_t62_t z_os_hostArchName(void);
static z_t62_t z_os_hostArchName(void) {
#if defined(__x86_64__) || defined(_M_X64)
    return z_t62_new("x86_64");
#elif defined(__aarch64__) || defined(_M_ARM64)
    return z_t62_new("aarch64");
#else
    return z_t62_new("other");
#endif
}

/* os.hostOsName -- the OS family this translation unit was compiled for,
   resolved by the C preprocessor. A NAME rather than a variant so the runtime
   needs to know nothing about `platform`'s kinds: `zc` maps it to a
   `platform.oskind` arm when it fills that unit in for the build it is
   performing. Falls through to `other` on an unrecognised host. */
static z_t62_t z_os_hostOsName(void);
static z_t62_t z_os_hostOsName(void) {
#if defined(__linux__)
    return z_t62_new("linux");
#elif defined(__APPLE__)
    return z_t62_new("darwin");
#elif defined(_WIN32)
    return z_t62_new("windows");
#else
    return z_t62_new("other");
#endif
}

/* os.monotonicMillis -- milliseconds on the monotonic clock. Only
   differences are meaningful (the epoch is arbitrary, typically boot).
   Infallible: CLOCK_MONOTONIC cannot fail on a supported platform. */
#include <time.h>
static int64_t z_os_monotonicMillis(void);
static int64_t z_os_monotonicMillis(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + (int64_t)(ts.tv_nsec / 1000000);
}

/* os.pid -- getpid. pid_t fits in int32_t on every supported
   platform (Linux caps at 4_194_304 by default). */
static int32_t z_os_pid(void);
static int32_t z_os_pid(void) {
    return (int32_t)getpid();
}


/* os.sleepMillis -- suspend the calling process for ms milliseconds.
   Restarts after EINTR so the full duration always elapses. */
#include <time.h>
static void z_os_sleepMillis(int64_t ms);
static void z_os_sleepMillis(int64_t ms) {
    if (ms <= 0) return;
    struct timespec req;
    req.tv_sec = (time_t)(ms / 1000);
    req.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&req, &req) != 0 && errno == EINTR) {
    }
}

/* z_os_spawn_start -- start argv as a child with posix_spawnp, the start
   os.spawn and os.spawnAsync share. argv[0] is resolved via PATH.
   stdout->outPath, stderr->errPath (each O_WRONLY|O_CREAT|O_TRUNC); an empty
   out/err path inherits the parent's fd, and empty out+err inherits stdin too
   (else stdin is /dev/null). A non-empty cwd is the child's working directory.

   The redirection files are opened in the parent, close-on-exec, before the
   child starts, so the child's cwd cannot change their resolution and no
   other child started meanwhile inherits them; the child receives them on
   0/1/2 through file actions (dup2 clears close-on-exec on the copy).
   posix_spawnp, unlike fork, is safe in a program that runs threads: the
   child runs no code of ours between its start and the exec. Answers the
   child's pid; -1 when the redirections could not be opened, the directory
   could not be entered, or the program could not be executed (the spawn
   reports each). argv element buffers are NUL-terminated and borrowed. */
#include <spawn.h>
extern char** environ;
static pid_t z_os_spawn_start(
    const z_t526_t* argv, z_t82_t cwd, z_t82_t outPath,
    z_t82_t errPath
);
static pid_t z_os_spawn_start(
    const z_t526_t* argv, z_t82_t cwd, z_t82_t outPath,
    z_t82_t errPath
) {
    if (argv->length == 0) return -1;
    char** c_argv = (char**)z_xmalloc((argv->length + 1) * sizeof(char*));
    for (uint64_t i = 0; i < argv->length; i++) {
        c_argv[i] = argv->data[i].data;
    }
    c_argv[argv->length] = NULL;
    int inherit_out = (outPath.size == 0);
    int inherit_err = (errPath.size == 0);
    int inherit_in = (inherit_out && inherit_err);
    char* cwd_c = z_sv_to_cstr(cwd);
    char* out_c = inherit_out ? NULL : z_sv_to_cstr(outPath);
    char* err_c = inherit_err ? NULL : z_sv_to_cstr(errPath);
    int out_fd = inherit_out ? -1 : open(out_c, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    int err_fd = inherit_err ? -1 : open(err_c, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    int null_fd = inherit_in ? -1 : open("/dev/null", O_RDONLY | O_CLOEXEC);
    pid_t pid = -1;
    int setup_ok = (inherit_out || out_fd >= 0) && (inherit_err || err_fd >= 0)
                   && (inherit_in || null_fd >= 0);
    if (setup_ok) {
        posix_spawn_file_actions_t fa;
        posix_spawn_file_actions_init(&fa);
        int fa_ok = 1;
        if (cwd.size > 0 && posix_spawn_file_actions_addchdir_np(&fa, cwd_c) != 0) fa_ok = 0;
        if (!inherit_in && posix_spawn_file_actions_adddup2(&fa, null_fd, 0) != 0) fa_ok = 0;
        if (!inherit_out && posix_spawn_file_actions_adddup2(&fa, out_fd, 1) != 0) fa_ok = 0;
        if (!inherit_err && posix_spawn_file_actions_adddup2(&fa, err_fd, 2) != 0) fa_ok = 0;
        pid_t child = -1;
        if (fa_ok && posix_spawnp(&child, c_argv[0], &fa, NULL, c_argv, environ) == 0) pid = child;
        posix_spawn_file_actions_destroy(&fa);
    }
    if (out_fd >= 0) close(out_fd);
    if (err_fd >= 0) close(err_fd);
    if (null_fd >= 0) close(null_fd);
    free(cwd_c);
    free(out_c);
    free(err_c);
    free(c_argv);
    return pid;
}
/* os.spawn -- start argv as a child (z_os_spawn_start: PATH resolution,
   redirections, cwd) and wait for it. Returns the child's exit status; 127
   on exec/setup failure; 124 if timeoutSecs > 0 and the child outlived it
   (SIGKILLed). timeoutSecs <= 0 waits forever.

   The timeout waits on a pidfd with poll, so it touches no process-wide
   state (no signal handler, no alarm) and another thread's spawn is not
   disturbed. A kernel without pidfd_open (ENOSYS) is polled with WNOHANG
   every 10ms instead. */
#include <time.h>
static int32_t z_os_spawn_status(int wst) {
    if (WIFEXITED(wst)) return (int32_t)WEXITSTATUS(wst);
    return 127;
}
static int32_t z_os_spawn(
    z_t526_t* argv, z_t82_t cwd, z_t82_t outPath,
    z_t82_t errPath, int32_t timeoutSecs
);
static int32_t z_os_spawn(
    z_t526_t* argv, z_t82_t cwd, z_t82_t outPath,
    z_t82_t errPath, int32_t timeoutSecs
) {
    pid_t pid = z_os_spawn_start(argv, cwd, outPath, errPath);
    if (pid < 0) return 127;
    int wst = 0;
    if (timeoutSecs <= 0) {
        while (waitpid(pid, &wst, 0) < 0) {
            if (errno != EINTR) return 127;
        }
        return z_os_spawn_status(wst);
    }
    int64_t budget = (int64_t)timeoutSecs * 1000;
    int pfd = -1;
#ifdef SYS_pidfd_open
    pfd = (int)syscall(SYS_pidfd_open, pid, 0);
#endif
    if (pfd >= 0) {
        struct pollfd p = { pfd, POLLIN, 0 };
        struct timespec t0;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        int ready = 0;
        for (;;) {
            struct timespec t1;
            clock_gettime(CLOCK_MONOTONIC, &t1);
            int64_t spent = (int64_t)(t1.tv_sec - t0.tv_sec) * 1000
                          + (int64_t)(t1.tv_nsec - t0.tv_nsec) / 1000000;
            if (spent >= budget) break;
            int r = poll(&p, 1, (int)(budget - spent));
            if (r > 0) { ready = 1; break; }
            if (r < 0 && errno != EINTR) break;
        }
        close(pfd);
        if (!ready) {
            kill(pid, SIGKILL);
            while (waitpid(pid, &wst, 0) < 0 && errno == EINTR) {}
            return 124;
        }
        while (waitpid(pid, &wst, 0) < 0) {
            if (errno != EINTR) return 127;
        }
        return z_os_spawn_status(wst);
    }
    for (int64_t waited = 0; ; waited += 10) {
        pid_t r = waitpid(pid, &wst, WNOHANG);
        if (r == pid) return z_os_spawn_status(wst);
        if (r < 0 && errno != EINTR) return 127;
        if (waited >= budget) break;
        struct timespec ts = { 0, 10 * 1000000L };
        nanosleep(&ts, NULL);
    }
    kill(pid, SIGKILL);
    while (waitpid(pid, &wst, 0) < 0 && errno == EINTR) {}
    return 124;
}
/* Shared by tcc.available and tcc.compileToExe: the libtcc entry points and
   the dlopen that finds them.

   libtcc is LOADED, never linked. That is a licence requirement, not a
   preference -- tinycc is LGPL-2.1 inside a permissive tree -- and
   `make static-tcc-guard` fails the build if any tcc symbol reaches a
   binary. So the names below are strings, resolved at the point of use;
   nothing here creates a link-time dependency, and a zc built without a
   tcc beside it is a zc that reports 127 rather than one that fails to
   start.

   The library lives at <tccDir>/libtcc.so, the same directory that holds
   the runtime payload tcc_set_lib_path needs. One directory, one answer. */
#include <dlfcn.h>
typedef struct TCCState z_tcc_State;
typedef void z_tcc_ErrorFunc(void* opaque, const char* msg);

typedef struct {
    void* handle;
    z_tcc_State* (*nw)(void);
    void (*del)(z_tcc_State*);
    void (*set_lib_path)(z_tcc_State*, const char*);
    void (*set_error_func)(z_tcc_State*, void*, z_tcc_ErrorFunc*);
    int (*set_options)(z_tcc_State*, const char*);
    int (*set_output_type)(z_tcc_State*, int);
    int (*add_file)(z_tcc_State*, const char*);
    int (*add_library)(z_tcc_State*, const char*);
    int (*output_file)(z_tcc_State*, const char*);
} z_tcc_api_t;

#define Z_TCC_OUTPUT_EXE 2
#define Z_TCC_OUTPUT_OBJ 3

/* diagnostics go to stderr verbatim, so a program reports the same text
   whichever mode built it. */
static void z_tcc_on_error(void* opaque, const char* msg) {
    (void)opaque;
    fprintf(stderr, "%s\n", msg);
}

static char* z_tcc_lib_path(z_t82_t tccDir) {
    char* dir = z_sv_to_cstr(tccDir);
    size_t n = strlen(dir);
    char* p = (char*)z_xmalloc(n + sizeof("/libtcc.so"));
    memcpy(p, dir, n);
    memcpy(p + n, "/libtcc.so", sizeof("/libtcc.so"));
    free(dir);
    return p;
}

/* 1 when every entry point resolved. A partial load is a failed load: a
   libtcc missing one of these is not one this code can drive. */
static int z_tcc_open(z_tcc_api_t* a, z_t82_t tccDir) {
    char* path = z_tcc_lib_path(tccDir);
    memset(a, 0, sizeof(*a));
    a->handle = dlopen(path, RTLD_NOW | RTLD_LOCAL);
    free(path);
    if (!a->handle) return 0;
    *(void**)&a->nw = dlsym(a->handle, "tcc_new");
    *(void**)&a->del = dlsym(a->handle, "tcc_delete");
    *(void**)&a->set_lib_path = dlsym(a->handle, "tcc_set_lib_path");
    *(void**)&a->set_error_func = dlsym(a->handle, "tcc_set_error_func");
    *(void**)&a->set_options = dlsym(a->handle, "tcc_set_options");
    *(void**)&a->set_output_type = dlsym(a->handle, "tcc_set_output_type");
    *(void**)&a->add_file = dlsym(a->handle, "tcc_add_file");
    *(void**)&a->add_library = dlsym(a->handle, "tcc_add_library");
    *(void**)&a->output_file = dlsym(a->handle, "tcc_output_file");
    if (a->nw && a->del && a->set_lib_path && a->set_error_func
        && a->set_options && a->set_output_type && a->add_file
        && a->add_library && a->output_file) {
        return 1;
    }
    dlclose(a->handle);
    a->handle = NULL;
    return 0;
}

static void z_tcc_close(z_tcc_api_t* a) {
    if (a->handle) dlclose(a->handle);
    a->handle = NULL;
}

/* tcc.compileToExe -- compile `csrc` and link it to the executable `exe`,
   in this process, through libtcc loaded from `tccDir`.

   The result is a file on disk (TCC_OUTPUT_EXE), never a run in memory:
   in-process buys the fast COMPILE, and the program still executes as its
   own child, so exit codes, signals and the leak corpus are unaffected and
   a crashing program cannot take zc down with it.

   `tccDir` is also handed to tcc_set_lib_path -- tcc's runtime payload is
   fixed when tcc is configured, so a relocated one cannot resolve even
   stddef.h until it is told. `cflags` is parsed by tcc itself (the same
   spelling as the command line); `libs` are the `-l` names the emitted C
   declared, with -lm appended the way the spawned path appends it; `objs`
   are object files linked in after the source.

   Returns 0 on success, 1 when tcc rejected the program or the link
   failed, and 127 when libtcc could not be loaded -- the code os.spawn
   already uses for "could not run the compiler", so the driver reports
   both through one path rather than growing a second. */
static int32_t z_tcc_compileToExe(
    z_t82_t csrc, z_t82_t exe, z_t82_t tccDir,
    bool release, z_t82_t cflags, const z_t526_t* libs,
    const z_t526_t* objs
);
static int32_t z_tcc_compileToExe(
    z_t82_t csrc, z_t82_t exe, z_t82_t tccDir,
    bool release, z_t82_t cflags, const z_t526_t* libs,
    const z_t526_t* objs
) {
    z_tcc_api_t a;
    if (!z_tcc_open(&a, tccDir)) return 127;

    z_tcc_State* s = a.nw();
    if (!s) {
        z_tcc_close(&a);
        return 127;
    }
    a.set_error_func(s, NULL, z_tcc_on_error);

    char* dir_c = z_sv_to_cstr(tccDir);
    a.set_lib_path(s, dir_c);
    free(dir_c);

    int32_t rc = 0;
    /* -g matches the spawned path's debug default; tcc has one optimisation
       level, so --release changes nothing here beyond dropping -g. */
    if (!release && a.set_options(s, "-g") == -1) rc = 1;

    if (rc == 0 && cflags.size > 0) {
        char* cf = z_sv_to_cstr(cflags);
        if (a.set_options(s, cf) == -1) rc = 1;
        free(cf);
    }
    if (rc == 0 && a.set_output_type(s, Z_TCC_OUTPUT_EXE) == -1) rc = 1;

    if (rc == 0) {
        char* src_c = z_sv_to_cstr(csrc);
        if (a.add_file(s, src_c) == -1) rc = 1;
        free(src_c);
    }
    if (rc == 0) {
        for (uint64_t i = 0; i < objs->length; i++) {
            if (a.add_file(s, objs->data[i].data) == -1) {
                rc = 1;
                break;
            }
        }
    }
    if (rc == 0) {
        for (uint64_t i = 0; i < libs->length; i++) {
            if (a.add_library(s, libs->data[i].data) == -1) {
                rc = 1;
                break;
            }
        }
    }
    if (rc == 0 && a.add_library(s, "m") == -1) rc = 1;

    if (rc == 0) {
        char* exe_c = z_sv_to_cstr(exe);
        if (a.output_file(s, exe_c) == -1) rc = 1;
        free(exe_c);
    }

    a.del(s);
    z_tcc_close(&a);
    return rc;
}

/* tcc.compileToObject -- compile `csrc` to the object file `obj`, in this
   process, through libtcc loaded from `tccDir` (TCC_OUTPUT_OBJ). `cflags` is
   parsed by tcc itself, the -D defines among them. Codes as compileToExe's:
   0 on success, 1 when tcc rejected the source, 127 when libtcc could not be
   loaded. */
static int32_t z_tcc_compileToObject(
    z_t82_t csrc, z_t82_t obj, z_t82_t tccDir,
    z_t82_t cflags
);
static int32_t z_tcc_compileToObject(
    z_t82_t csrc, z_t82_t obj, z_t82_t tccDir,
    z_t82_t cflags
) {
    z_tcc_api_t a;
    if (!z_tcc_open(&a, tccDir)) return 127;

    z_tcc_State* s = a.nw();
    if (!s) {
        z_tcc_close(&a);
        return 127;
    }
    a.set_error_func(s, NULL, z_tcc_on_error);

    char* dir_c = z_sv_to_cstr(tccDir);
    a.set_lib_path(s, dir_c);
    free(dir_c);

    int32_t rc = 0;
    if (cflags.size > 0) {
        char* cf = z_sv_to_cstr(cflags);
        if (a.set_options(s, cf) == -1) rc = 1;
        free(cf);
    }
    if (rc == 0 && a.set_output_type(s, Z_TCC_OUTPUT_OBJ) == -1) rc = 1;
    if (rc == 0) {
        char* src_c = z_sv_to_cstr(csrc);
        if (a.add_file(s, src_c) == -1) rc = 1;
        free(src_c);
    }
    if (rc == 0) {
        char* obj_c = z_sv_to_cstr(obj);
        if (a.output_file(s, obj_c) == -1) rc = 1;
        free(obj_c);
    }

    a.del(s);
    z_tcc_close(&a);
    return rc;
}

